import { NextRequest, NextResponse } from 'next/server';

// ESP32 common vendor IDs
const ESP32_VENDOR_IDS: Record<string, string> = {
  '10c4': 'Silicon Labs (CP210x)',
  '1a86': 'WCH (CH340)',
  '0403': 'FTDI',
  '303a': 'Espressif (ESP32 native USB)',
  '2341': 'Arduino',
};

interface SerialPortInfo {
  path: string;
  manufacturer?: string;
  vendorId?: string;
  productId?: string;
  serialNumber?: string;
  pnpId?: string;
  isEsp32?: boolean;
  chipType?: string;
}

interface SerialResponse {
  ports: SerialPortInfo[];
  serialportAvailable: boolean;
  note?: string;
}

async function tryListPorts(): Promise<{
  ports: SerialPortInfo[];
  available: boolean;
  error?: string;
}> {
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const serialport = await import(/* webpackIgnore: true */ 'serialport').catch(() => null) as Record<string, unknown> | null;
    const SerialPort = serialport
      ? (serialport.SerialPort as { list: () => Promise<Array<Record<string, string>>> } | undefined)
      : undefined;

    if (SerialPort && typeof SerialPort.list === 'function') {
      const rawPorts = await SerialPort.list();

      const ports: SerialPortInfo[] = rawPorts.map((port: Record<string, string>) => ({
        path: port.path || '',
        manufacturer: port.manufacturer || undefined,
        vendorId: port.vendorId || undefined,
        productId: port.productId || undefined,
        serialNumber: port.serialNumber || undefined,
        pnpId: port.pnpId || undefined,
        isEsp32: isEsp32Port(port),
        chipType: identifyChipType(port),
      }));

      return { ports, available: true };
    }

    return { ports: [], available: false, error: 'SerialPort.list not available' };
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown error';
    return { ports: [], available: false, error: message };
  }
}

function isEsp32Port(port: Record<string, string>): boolean {
  const vendorId = (port.vendorId || '').toLowerCase().replace(/^0x/, '');
  return Object.keys(ESP32_VENDOR_IDS).includes(vendorId);
}

function identifyChipType(port: Record<string, string>): string | undefined {
  const vendorId = (port.vendorId || '').toLowerCase().replace(/^0x/, '');

  if (vendorId === '10c4') return 'CP210x';
  if (vendorId === '1a86') return 'CH340';
  if (vendorId === '0403') return 'FTDI';
  if (vendorId === '303a') return 'ESP32 Native USB';
  if (vendorId === '2341') return 'Arduino';

  return undefined;
}

// GET: List available serial ports
export async function GET() {
  const result = await tryListPorts();

  const response: SerialResponse = {
    ports: result.ports,
    serialportAvailable: result.available,
  };

  if (!result.available) {
    response.note =
      'serialport npm package is not available. Serial port detection is disabled. ' +
      'Install it with: npm install serialport. ' +
      (result.error ? `Error: ${result.error}` : '');
  }

  // If no ports found, provide helpful information
  if (result.available && result.ports.length === 0) {
    response.note =
      'No serial ports detected. Make sure your ESP32 is connected via USB ' +
      'and the appropriate drivers are installed (CP210x, CH340, or FTDI).';
  }

  return NextResponse.json(response);
}

// POST: Handle serial port actions (connect, disconnect, send)
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { action, data, port, baudRate } = body as {
      action?: string;
      data?: string;
      port?: string;
      baudRate?: number;
    };

    switch (action) {
      case 'connect': {
        // In a real desktop app, this would open the serial port
        // For the web IDE, we simulate the connection
        const effectiveBaud = baudRate || 115200;
        const effectivePort = port || '/dev/ttyUSB0';

        return NextResponse.json({
          success: true,
          message: `Connected to ${effectivePort} at ${effectiveBaud} baud (simulated)`,
          port: effectivePort,
          baudRate: effectiveBaud,
          note: 'Serial connection is simulated in the web IDE. For real serial communication, use the desktop app.',
        });
      }

      case 'disconnect': {
        return NextResponse.json({
          success: true,
          message: 'Disconnected from serial port',
        });
      }

      case 'send': {
        if (!data) {
          return NextResponse.json(
            { success: false, error: 'No data provided to send' },
            { status: 400 }
          );
        }

        return NextResponse.json({
          success: true,
          message: `Sent: ${data} (simulated)`,
          note: 'Serial data transmission is simulated in the web IDE.',
        });
      }

      case 'list': {
        // Reuse GET logic for listing ports
        const listResult = await tryListPorts();
        return NextResponse.json({
          success: true,
          ports: listResult.ports,
          serialportAvailable: listResult.available,
        });
      }

      default:
        return NextResponse.json(
          { success: false, error: `Unknown action: ${action}` },
          { status: 400 }
        );
    }
  } catch (error) {
    return NextResponse.json(
      {
        success: false,
        error: `Serial operation failed: ${error instanceof Error ? error.message : 'Unknown error'}`,
      },
      { status: 500 }
    );
  }
}
